        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<H and 0<=b<W) or g[a][b]!=col: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1): st.append((a+da,b+db))
                out.append((col,cells))
    return out
