def align(g):
    cs=comps(g); mint=min(min(a for a,_ in cells) for _,cells in cs)
    res=[[0]*len(g[0]) for _ in g]
    for col,cells in cs:
        off=min(a for a,_ in cells)-mint
        for a,b in cells: res[a-off][b]=col
    return res
